  await page.$eval('[data-motion-content-panel] .crow:not([hidden]) [data-motion-upload]',input=>{const svg='<svg xmlns="http://www.w3.org/2000/svg" width="301" height="301"><rect width="301" height="301" fill="#112233" opacity="0.5"/></svg>',transfer=new DataTransfer();transfer.items.add(new File([svg],'Alpha.svg',{type:'image/svg+xml'}));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));});await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe').contentDocument.querySelector('[data-id="'+id+'"] img')?.naturalWidth===301,{},start[0].id);await ready();for(const progress of [.08,.75])for(const {pixel} of await sourcePixels(progress)){assert.ok(Math.abs(pixel[3]-128)<5,JSON.stringify({progress,pixel}));for(let i=0;i<3;i++)assert.ok(Math.abs(pixel[i]-[17,34,51][i])<5);}console.log('Image Trail pixels: age-sorted repeated sources, real overlap/corner picking, both arc crop copies and intrinsic source alpha OK');await change('[data-motion-stream="cornerRadius"]','3');await page.click('[data-motion-layer="'+start[0].id+'"]');
  // Reordering moves the source and its authored crop together.
